#!/usr/bin/env bun
/**
 * Taskboard CLI — a dependency-free command-line task manager for Bun.
 *
 * Entry point: `bun run src/cli.ts ...`
 *
 * Every invocation prints exactly one JSON value to stdout. Diagnostics go to
 * stderr and failures exit non-zero.
 */

import { resolve, dirname, basename, join } from "node:path";
import { writeFileSync, readFileSync, existsSync, renameSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { spawnSync } from "node:child_process";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface Task {
  id: number;
  title: string;
  status: "open" | "done";
  createdAt: string; // ISO 8601
  completedAt: string | null; // ISO 8601
  tags: string[];
  due: string | null; // YYYY-MM-DD
}

interface Database {
  nextId: number;
  tasks: Task[];
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

class CliError extends Error {
  constructor(public code: number, message: string) {
    super(message);
    this.name = "CliError";
  }
}

// ---------------------------------------------------------------------------
// Date helpers
// ---------------------------------------------------------------------------

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** Validate a YYYY-MM-DD string is a real calendar date. Returns the normalized string. */
function validateDate(input: string, field: string): string {
  const m = DATE_RE.exec(input);
  if (!m) {
    throw new CliError(2, `${field}: invalid date "${input}", expected YYYY-MM-DD`);
  }
  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  // Construct a Date at noon UTC to avoid timezone edge cases, then verify round-trip.
  const d = new Date(Date.UTC(year, month - 1, day, 12, 0, 0, 0));
  if (
    d.getUTCFullYear() !== year ||
    d.getUTCMonth() !== month - 1 ||
    d.getUTCDate() !== day
  ) {
    throw new CliError(2, `${field}: impossible date "${input}"`);
  }
  return input;
}

/** Today's date in the local timezone as YYYY-MM-DD. */
function todayLocal(): string {
  const d = new Date();
  const y = d.getFullYear();
  const mo = String(d.getMonth() + 1).padStart(2, "0");
  const da = String(d.getDate()).padStart(2, "0");
  return `${y}-${mo}-${da}`;
}

// ---------------------------------------------------------------------------
// Storage
// ---------------------------------------------------------------------------

function dbPath(): string {
  const env = process.env.TASKBOARD_FILE;
  if (env && env.trim() !== "") return resolve(env);
  return resolve(".taskboard.json");
}

function emptyDb(): Database {
  return { nextId: 1, tasks: [] };
}

function loadDb(path: string): Database {
  if (!existsSync(path)) {
    return emptyDb();
  }
  let raw: string;
  try {
    raw = readFileSync(path, "utf8");
  } catch (e) {
    throw new CliError(1, `cannot read database: ${(e as Error).message}`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new CliError(1, `malformed database: ${(e as Error).message}`);
  }
  const db = validateDb(parsed);
  return db;
}

function validateDb(parsed: unknown): Database {
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new CliError(1, "malformed database: expected an object");
  }
  const obj = parsed as Record<string, unknown>;
  if (typeof obj.nextId !== "number" || !Number.isInteger(obj.nextId) || obj.nextId < 1) {
    throw new CliError(1, "malformed database: nextId must be a positive integer");
  }
  if (!Array.isArray(obj.tasks)) {
    throw new CliError(1, "malformed database: tasks must be an array");
  }
  const tasks: Task[] = [];
  const seenIds = new Set<number>();
  for (let i = 0; i < obj.tasks.length; i++) {
    const t = obj.tasks[i];
    tasks.push(validateTask(t, i));
    if (seenIds.has(tasks[i].id)) {
      throw new CliError(1, `malformed database: duplicate id ${tasks[i].id}`);
    }
    seenIds.add(tasks[i].id);
  }
  return { nextId: obj.nextId, tasks };
}

function validateTask(t: unknown, index: number): Task {
  if (typeof t !== "object" || t === null || Array.isArray(t)) {
    throw new CliError(1, `malformed database: task[${index}] is not an object`);
  }
  const o = t as Record<string, unknown>;
  const id = o.id;
  if (typeof id !== "number" || !Number.isInteger(id) || id < 1) {
    throw new CliError(1, `malformed database: task[${index}].id must be a positive integer`);
  }
  if (typeof o.title !== "string") {
    throw new CliError(1, `malformed database: task[${index}].title must be a string`);
  }
  if (o.status !== "open" && o.status !== "done") {
    throw new CliError(1, `malformed database: task[${index}].status must be "open" or "done"`);
  }
  if (typeof o.createdAt !== "string") {
    throw new CliError(1, `malformed database: task[${index}].createdAt must be a string`);
  }
  if (o.completedAt !== null && typeof o.completedAt !== "string") {
    throw new CliError(1, `malformed database: task[${index}].completedAt must be a string or null`);
  }
  if (!Array.isArray(o.tags) || o.tags.some((x) => typeof x !== "string")) {
    throw new CliError(1, `malformed database: task[${index}].tags must be an array of strings`);
  }
  if (o.due !== null && typeof o.due !== "string") {
    throw new CliError(1, `malformed database: task[${index}].due must be a string or null`);
  }
  return {
    id,
    title: o.title,
    status: o.status,
    createdAt: o.createdAt,
    completedAt: o.completedAt as string | null,
    tags: o.tags as string[],
    due: o.due as string | null,
  };
}

/** Atomically write the database: write a sibling temp file then rename. */
function saveDb(path: string, db: Database): void {
  const dir = dirname(path);
  const base = basename(path);
  const tmpName = `.${base}.tmp.${process.pid}.${Date.now()}`;
  const tmpPath = join(dir, tmpName);
  const data = JSON.stringify(db, null, 2) + "\n";
  try {
    writeFileSync(tmpPath, data, { encoding: "utf8" });
    renameSync(tmpPath, path);
  } catch (e) {
    // Best-effort cleanup of the temp file on failure.
    try {
      if (existsSync(tmpPath)) rmSync(tmpPath, { force: true });
    } catch {
      // ignore
    }
    throw new CliError(1, `cannot write database: ${(e as Error).message}`);
  }
}

// ---------------------------------------------------------------------------
// Argument parsing
// ---------------------------------------------------------------------------

interface ParsedArgs {
  flags: Record<string, string>;
  positionals: string[];
}

/** Known flag names for a command (without leading --). */
function parseArgs(argv: string[], knownFlags: Set<string>): ParsedArgs {
  const flags: Record<string, string> = {};
  const positionals: string[] = [];
  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];
    if (arg === "--") {
      // Everything after -- is positional.
      i++;
      while (i < argv.length) {
        positionals.push(argv[i]);
        i++;
      }
      break;
    }
    if (arg.startsWith("--")) {
      // --flag=value form
      const eq = arg.indexOf("=");
      if (eq !== -1) {
        const name = arg.slice(2, eq);
        const value = arg.slice(eq + 1);
        if (!knownFlags.has(name)) {
          throw new CliError(2, `unknown flag: --${name}`);
        }
        if (name in flags) {
          throw new CliError(2, `duplicate flag: --${name}`);
        }
        flags[name] = value;
        i++;
        continue;
      }
      // --flag value form
      const name = arg.slice(2);
      if (!knownFlags.has(name)) {
        throw new CliError(2, `unknown flag: --${name}`);
      }
      if (name in flags) {
        throw new CliError(2, `duplicate flag: --${name}`);
      }
      if (i + 1 >= argv.length) {
        throw new CliError(2, `flag --${name} requires a value`);
      }
      flags[name] = argv[i + 1];
      i += 2;
      continue;
    }
    // positional
    positionals.push(arg);
    i++;
  }
  return { flags, positionals };
}

// ---------------------------------------------------------------------------
// Tag normalization
// ---------------------------------------------------------------------------

function normalizeTags(input: string | undefined): string[] {
  if (input === undefined) return [];
  const parts = input.split(",").map((s) => s.trim().toLowerCase()).filter((s) => s !== "");
  const seen = new Set<string>();
  const out: string[] = [];
  for (const p of parts) {
    if (!seen.has(p)) {
      seen.add(p);
      out.push(p);
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Commands
// ---------------------------------------------------------------------------

function cmdAdd(argv: string[]): Task {
  const known = new Set(["title", "tags", "due"]);
  const { flags, positionals } = parseArgs(argv, known);
  if (positionals.length > 0) {
    throw new CliError(2, `add: unexpected positional argument: ${positionals[0]}`);
  }
  const title = flags.title;
  if (title === undefined) {
    throw new CliError(2, "add: --title is required");
  }
  if (title.trim() === "") {
    throw new CliError(2, "add: title must not be empty");
  }
  let due: string | null = null;
  if (flags.due !== undefined) {
    due = validateDate(flags.due, "due");
  }
  const tags = normalizeTags(flags.tags);

  const path = dbPath();
  const db = loadDb(path);
  const id = db.nextId;
  const task: Task = {
    id,
    title,
    status: "open",
    createdAt: new Date().toISOString(),
    completedAt: null,
    tags,
    due,
  };
  db.tasks.push(task);
  db.nextId = id + 1;
  saveDb(path, db);
  return task;
}

function cmdList(argv: string[]): Task[] {
  const known = new Set(["status", "tag", "overdue"]);
  const { flags, positionals } = parseArgs(argv, known);
  if (positionals.length > 0) {
    throw new CliError(2, `list: unexpected positional argument: ${positionals[0]}`);
  }
  let statusFilter: "open" | "done" | null = null;
  if (flags.status !== undefined) {
    if (flags.status !== "open" && flags.status !== "done") {
      throw new CliError(2, `list: --status must be "open" or "done", got "${flags.status}"`);
    }
    statusFilter = flags.status;
  }
  let tagFilter: string | null = null;
  if (flags.tag !== undefined) {
    tagFilter = flags.tag.trim().toLowerCase();
    if (tagFilter === "") {
      throw new CliError(2, "list: --tag must not be empty");
    }
  }
  let overdueDate: string | null = null;
  if (flags.overdue !== undefined) {
    overdueDate = validateDate(flags.overdue, "overdue");
  }

  const path = dbPath();
  const db = loadDb(path);
  let result = db.tasks.slice();
  if (statusFilter) {
    result = result.filter((t) => t.status === statusFilter);
  }
  if (tagFilter) {
    result = result.filter((t) => t.tags.includes(tagFilter));
  }
  if (overdueDate) {
    result = result.filter((t) => t.status === "open" && t.due !== null && t.due < overdueDate);
  }
  result.sort((a, b) => a.id - b.id);
  return result;
}

function findTask(db: Database, idStr: string): Task {
  const id = Number(idStr);
  if (!Number.isInteger(id) || String(id) !== idStr.trim() || id < 1) {
    throw new CliError(2, `invalid id: "${idStr}"`);
  }
  const task = db.tasks.find((t) => t.id === id);
  if (!task) {
    throw new CliError(1, `task ${id} not found`);
  }
  return task;
}

function cmdDone(argv: string[]): Task {
  const known = new Set<string>();
  const { flags, positionals } = parseArgs(argv, known);
  if (Object.keys(flags).length > 0) {
    // Should not happen since no flags are known, but parseArgs already errors.
  }
  if (positionals.length !== 1) {
    throw new CliError(2, "done: expected exactly one task id");
  }
  const path = dbPath();
  const db = loadDb(path);
  const task = findTask(db, positionals[0]);
  if (task.status === "done") {
    // Idempotent: return as-is without modifying completedAt.
    return task;
  }
  task.status = "done";
  task.completedAt = new Date().toISOString();
  saveDb(path, db);
  return task;
}

function cmdDelete(argv: string[]): { id: number; deleted: true } {
  const known = new Set<string>();
  const { flags, positionals } = parseArgs(argv, known);
  if (positionals.length !== 1) {
    throw new CliError(2, "delete: expected exactly one task id");
  }
  const path = dbPath();
  const db = loadDb(path);
  const task = findTask(db, positionals[0]);
  db.tasks = db.tasks.filter((t) => t.id !== task.id);
  saveDb(path, db);
  return { id: task.id, deleted: true };
}

function cmdStats(argv: string[]): { total: number; open: number; done: number; overdue: number } {
  const known = new Set<string>();
  const { flags, positionals } = parseArgs(argv, known);
  if (positionals.length > 0) {
    throw new CliError(2, `stats: unexpected positional argument: ${positionals[0]}`);
  }
  const today = todayLocal();
  const path = dbPath();
  const db = loadDb(path);
  const total = db.tasks.length;
  const open = db.tasks.filter((t) => t.status === "open").length;
  const done = db.tasks.filter((t) => t.status === "done").length;
  const overdue = db.tasks.filter(
    (t) => t.status === "open" && t.due !== null && t.due < today
  ).length;
  return { total, open, done, overdue };
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function main(argv: string[]): number {
  if (argv.length === 0) {
    throw new CliError(2, "no command given; expected one of: add, list, done, delete, stats");
  }
  const command = argv[0];
  const rest = argv.slice(1);
  let result: unknown;
  switch (command) {
    case "add":
      result = cmdAdd(rest);
      break;
    case "list":
      result = cmdList(rest);
      break;
    case "done":
      result = cmdDone(rest);
      break;
    case "delete":
      result = cmdDelete(rest);
      break;
    case "stats":
      result = cmdStats(rest);
      break;
    default:
      throw new CliError(2, `unknown command: ${command}`);
  }
  process.stdout.write(JSON.stringify(result) + "\n");
  return 0;
}

try {
  const code = main(process.argv.slice(2));
  process.exit(code);
} catch (e) {
  if (e instanceof CliError) {
    process.stderr.write(`error: ${e.message}\n`);
    process.exit(e.code);
  }
  process.stderr.write(`error: ${(e as Error).message}\n`);
  process.exit(1);
}

/**
 * Self-tests for Taskboard CLI.
 *
 * Runs the CLI as a subprocess in an isolated temp directory and verifies the
 * behaviour described in SPEC.md. Run with: `bun run test/selftest.ts`
 */

import { mkdtempSync, rmSync, writeFileSync, readFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

const CLI = join(import.meta.dir, "..", "src", "cli.ts");

let passed = 0;
let failed = 0;

function assert(cond: boolean, msg: string): void {
  if (cond) {
    passed++;
  } else {
    failed++;
    console.error(`  FAIL: ${msg}`);
  }
}

function assertEqual<T>(actual: T, expected: T, msg: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  assert(a === e, `${msg} (expected ${e}, got ${a})`);
}

interface RunResult {
  status: number;
  stdout: string;
  stderr: string;
}

function run(args: string[], env?: Record<string, string>, cwd?: string): RunResult {
  const fullEnv = { ...process.env, ...env };
  const r = spawnSync("bun", ["run", CLI, ...args], {
    cwd,
    env: fullEnv,
    encoding: "utf8",
  });
  return {
    status: r.status ?? -1,
    stdout: r.stdout ?? "",
    stderr: r.stderr ?? "",
  };
}

function parseJson<T = unknown>(s: string): T {
  return JSON.parse(s.trim());
}

function makeTempDir(): string {
  return mkdtempSync(join(tmpdir(), "taskboard-test-"));
}

// ---------------------------------------------------------------------------
// Test suites
// ---------------------------------------------------------------------------

function testAddBasic(): void {
  const dir = makeTempDir();
  try {
    const r = run(["add", "--title", "First task"], { TASKBOARD_FILE: join(dir, "db.json") });
    assert(r.status === 0, `add should exit 0 (stderr: ${r.stderr})`);
    const task = parseJson<any>(r.stdout);
    assertEqual(task.id, 1, "first task id");
    assertEqual(task.status, "open", "status open");
    assertEqual(task.title, "First task", "title");
    assertEqual(task.tags, [], "empty tags");
    assertEqual(task.due, null, "no due");
    assert(typeof task.createdAt === "string", "createdAt is string");
    assertEqual(task.completedAt, null, "completedAt null");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testAddTagsAndDue(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    const r = run(["add", "--title", "T2", "--tags", "Work, work, home", "--due", "2026-12-31"], env);
    assert(r.status === 0, `add exit 0 (stderr: ${r.stderr})`);
    const task = parseJson<any>(r.stdout);
    assertEqual(task.id, 1, "id");
    assertEqual(task.tags, ["work", "home"], "tags normalized + deduped");
    assertEqual(task.due, "2026-12-31", "due");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testAddEmptyTitleFails(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    const r = run(["add", "--title", "   "], env);
    assert(r.status !== 0, "empty title should fail");
    assert(r.stdout.trim() === "", "no stdout on failure");
    assert(r.stderr.length > 0, "stderr present");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testAddImpossibleDateFails(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    const r = run(["add", "--title", "X", "--due", "2026-02-30"], env);
    assert(r.status !== 0, "impossible date should fail");
    const r2 = run(["add", "--title", "X", "--due", "not-a-date"], env);
    assert(r2.status !== 0, "garbage date should fail");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testStableIdsAcrossProcesses(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    run(["add", "--title", "A"], env);
    run(["add", "--title", "B"], env);
    const r = run(["add", "--title", "C"], env);
    const t = parseJson<any>(r.stdout);
    assertEqual(t.id, 3, "third task id is 3 (stable across processes)");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testListSortedAndFiltered(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    run(["add", "--title", "A", "--tags", "x"], env);
    run(["add", "--title", "B", "--tags", "y", "--due", "2020-01-01"], env);
    run(["add", "--title", "C", "--tags", "x"], env);

    // list all
    let r = run(["list"], env);
    let arr = parseJson<any[]>(r.stdout);
    assertEqual(arr.length, 3, "list all length");
    assertEqual(arr.map((t) => t.id), [1, 2, 3], "sorted by id");

    // list by tag
    r = run(["list", "--tag", "x"], env);
    arr = parseJson<any[]>(r.stdout);
    assertEqual(arr.map((t) => t.id), [1, 3], "tag filter");

    // list by status
    run(["done", "1"], env);
    r = run(["list", "--status", "open"], env);
    arr = parseJson<any[]>(r.stdout);
    assertEqual(arr.map((t) => t.id), [2, 3], "status open filter");

    r = run(["list", "--status", "done"], env);
    arr = parseJson<any[]>(r.stdout);
    assertEqual(arr.map((t) => t.id), [1], "status done filter");

    // overdue: open tasks with due strictly before 2021-01-01
    r = run(["list", "--overdue", "2021-01-01"], env);
    arr = parseJson<any[]>(r.stdout);
    assertEqual(arr.map((t) => t.id), [2], "overdue filter");

    // overdue boundary: strictly before, so 2020-01-01 should NOT include due 2020-01-01
    r = run(["list", "--overdue", "2020-01-01"], env);
    arr = parseJson<any[]>(r.stdout);
    assertEqual(arr.length, 0, "overdue strictly before (boundary)");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testDoneIdempotent(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    run(["add", "--title", "A"], env);
    const r1 = run(["done", "1"], env);
    assert(r1.status === 0, "done exit 0");
    const t1 = parseJson<any>(r1.stdout);
    assertEqual(t1.status, "done", "status done");
    const ts1 = t1.completedAt;
    assert(typeof ts1 === "string", "completedAt set");

    // second done is idempotent — completedAt unchanged
    const r2 = run(["done", "1"], env);
    assert(r2.status === 0, "second done exit 0");
    const t2 = parseJson<any>(r2.stdout);
    assertEqual(t2.completedAt, ts1, "completedAt unchanged on repeat");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testDelete(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    run(["add", "--title", "A"], env);
    run(["add", "--title", "B"], env);
    const r = run(["delete", "1"], env);
    assert(r.status === 0, "delete exit 0");
    const list = parseJson<any[]>(run(["list"], env).stdout);
    assertEqual(list.map((t) => t.id), [2], "deleted task gone");
    // id 1 should not be reused
    run(["add", "--title", "C"], env);
    const list2 = parseJson<any[]>(run(["list"], env).stdout);
    assertEqual(list2.map((t) => t.id), [2, 3], "id not reused after delete");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testStats(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    run(["add", "--title", "A", "--due", "2020-01-01"], env); // overdue (open, due in past)
    run(["add", "--title", "B"], env); // open
    run(["add", "--title", "C", "--due", "2099-01-01"], env); // open, future due
    run(["done", "1"], env); // now done, no longer overdue
    const r = run(["stats"], env);
    assert(r.status === 0, "stats exit 0");
    const s = parseJson<any>(r.stdout);
    assertEqual(s.total, 3, "stats total");
    assertEqual(s.open, 2, "stats open");
    assertEqual(s.done, 1, "stats done");
    assertEqual(s.overdue, 0, "stats overdue (done task not counted)");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testMissingTaskFails(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    run(["add", "--title", "A"], env);
    const r = run(["done", "99"], env);
    assert(r.status !== 0, "done on missing task fails");
    const r2 = run(["delete", "99"], env);
    assert(r2.status !== 0, "delete on missing task fails");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testUnknownCommandFails(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    const r = run(["frobnicate"], env);
    assert(r.status !== 0, "unknown command fails");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testUnknownFlagFails(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    const r = run(["add", "--title", "X", "--bogus", "y"], env);
    assert(r.status !== 0, "unknown flag fails");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testMalformedDbFails(): void {
  const dir = makeTempDir();
  try {
    const dbFile = join(dir, "db.json");
    writeFileSync(dbFile, "{not valid json", "utf8");
    const env = { TASKBOARD_FILE: dbFile };
    const r = run(["list"], env);
    assert(r.status !== 0, "malformed db fails");
    // data must not be silently replaced
    const after = readFileSync(dbFile, "utf8");
    assert(after === "{not valid json", "malformed db not replaced");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testAtomicWrite(): void {
  const dir = makeTempDir();
  try {
    const dbFile = join(dir, "db.json");
    const env = { TASKBOARD_FILE: dbFile };
    run(["add", "--title", "A"], env);
    // After a successful write, no leftover temp files should remain.
    const entries = require("node:fs").readdirSync(dir);
    const temps = entries.filter((f: string) => f.startsWith(".db.json.tmp"));
    assert(temps.length === 0, "no leftover temp files");
    // The db file should be valid JSON.
    JSON.parse(readFileSync(dbFile, "utf8"));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testEqualsFlagForm(): void {
  const dir = makeTempDir();
  try {
    const env = { TASKBOARD_FILE: join(dir, "db.json") };
    const r = run(["add", "--title=Hello", "--tags=a,b"], env);
    assert(r.status === 0, "--flag=value form works");
    const t = parseJson<any>(r.stdout);
    assertEqual(t.title, "Hello", "title via = form");
    assertEqual(t.tags, ["a", "b"], "tags via = form");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testDefaultFilePath(): void {
  const dir = makeTempDir();
  try {
    // No TASKBOARD_FILE set → uses .taskboard.json in cwd
    const r = run(["add", "--title", "X"], {}, dir);
    assert(r.status === 0, "add with default path exit 0");
    assert(existsSync(join(dir, ".taskboard.json")), "default file created");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

